-- 1) School
insert into public.schools (name, slug) values ('De Kleine Wereld', 'de-kleine-wereld')
on conflict (slug) do nothing;

-- 2) Klas 3A met namenlijst
insert into public.classes (school_id, name, grade, pupils)
select id, '3A', 3,
 '["George","Alvin","Mohammed Amin","Duha","Nawfal","Adam","Juf Mariëlle","Rayen","Yassir","Alen","Laila","Defne","Amal","Salomao","Taha","Atacan","Caner","Rania","Dina"]'::jsonb
from public.schools where slug = 'de-kleine-wereld'
and not exists (select 1 from public.classes c where c.name = '3A' and c.school_id = public.schools.id);

-- Vak aanvullen voor de Ruimte Quiz als die al eerder (zonder vak-kolom) werd aangemaakt
update public.quizzes set vak='Wereldoriëntatie' where vak is null and title='Ruimte Quiz' and school_id is null;

-- 3) Algemene quiz: Ruimte (beschikbaar voor alle scholen)
insert into public.quizzes (school_id, title, theme, vak, emoji, grade_min, grade_max, questions)
select null, 'Ruimte Quiz', 'Ruimte', 'Wereldoriëntatie', '🪐', 2, 4, '[{"q": "Welke planeet in ons zonnestelsel is de allergrootste?", "a": [{"t": "Mars", "ok": false, "e": "Niet helemaal! Mars is een stuk kleiner en staat bekend om zijn rode kleur."}, {"t": "Jupiter", "ok": true, "e": "Knap! Jupiter is reusachtig groot. Er zouden wel meer dan 1.300 aardes in passen!"}, {"t": "Saturnus", "ok": false, "e": "Bijna! Saturnus is heel groot door zijn prachtige ringen, maar Jupiter is toch echt de winnaar."}, {"t": "Aarde", "ok": false, "e": "Fout! De aarde is ons thuis, maar vergeleken met andere planeten is ze maar klein."}]}, {"q": "Hoe heet de eerste hond die naar de ruimte ging?", "a": [{"t": "Lakei", "ok": false, "e": "Haha, nee! Een lakei is een soort bediende. Deze hond heette anders…"}, {"t": "Laika", "ok": true, "e": "Juist! Laika vloog in 1957 als eerste hond de ruimte in, met de raket Spoetnik 2."}, {"t": "Kaila", "ok": false, "e": "Bijna goed geraden, maar de letters staan door elkaar. De hond heette Laika!"}]}, {"q": "Hoeveel planeten draaien er rond onze zon?", "a": [{"t": "5", "ok": false, "e": "Nee, het zijn er meer! Tel maar: Mercurius, Venus, Aarde, Mars, Jupiter, Saturnus, Uranus en Neptunus."}, {"t": "8", "ok": true, "e": "Super! Er zijn 8 planeten: Mercurius, Venus, Aarde, Mars, Jupiter, Saturnus, Uranus en Neptunus."}, {"t": "12", "ok": false, "e": "Dat zijn er te veel! Het zijn er 8. Vroeger telde men Pluto mee, maar die is nu een dwergplaneet."}, {"t": "100", "ok": false, "e": "Wauw, dat zou druk worden! Nee, er zijn 8 planeten."}]}, {"q": "Wat heeft een helikopter bovenop om te kunnen vliegen?", "a": [{"t": "Grote draaiende wieken", "ok": true, "e": "Juist! De wieken (de rotor) draaien heel snel rond en duwen de lucht naar beneden. Zo gaat de helikopter omhoog."}, {"t": "Een parachute", "ok": false, "e": "Nee! Een parachute helpt je juist om zachtjes naar beneden te zweven."}, {"t": "Een groot zeil", "ok": false, "e": "Nee, een zeil is voor een boot. Een helikopter heeft draaiende wieken."}]}, {"q": "Welke 2 planeten zijn ijskoud omdat ze heel ver van de zon staan?", "multi": 2, "a": [{"t": "Venus", "ok": false, "e": "Nee! Venus staat dicht bij de zon en is juist de heetste planeet van allemaal."}, {"t": "Uranus", "ok": true, "e": "Juist! Uranus staat heel ver van de zon en is ijskoud: meer dan 200 graden onder nul!"}, {"t": "Mercurius", "ok": false, "e": "Nee, Mercurius staat het dichtst bij de zon. Overdag is het daar gloeiend heet."}, {"t": "Neptunus", "ok": true, "e": "Juist! Neptunus is de verste planeet en is bibberkoud, met heel harde ijzige winden."}]}, {"q": "Op welke planeet wonen wij?", "a": [{"t": "Mars", "ok": false, "e": "Nee! Op Mars woont niemand… alleen een paar robots die daar rondrijden."}, {"t": "De Maan", "ok": false, "e": "De maan is geen planeet, maar een kleine bol die rond de aarde draait. En er woont niemand!"}, {"t": "Aarde", "ok": true, "e": "Natuurlijk! De aarde is de enige planeet die we kennen waar planten, dieren en mensen leven."}]}, {"q": "Welke planeet noemen we de rode planeet?", "a": [{"t": "Jupiter", "ok": false, "e": "Nee, Jupiter heeft bruine en witte strepen en een grote rode vlek, maar is niet de rode planeet."}, {"t": "Mars", "ok": true, "e": "Juist! Mars ziet rood door het roestige stof dat overal op de grond ligt."}, {"t": "Venus", "ok": false, "e": "Nee, Venus ziet eruit als een gele, wolkige bal."}, {"t": "Neptunus", "ok": false, "e": "Nee, Neptunus is juist heel diep blauw."}]}, {"q": "Wie bestuurt een vliegtuig?", "a": [{"t": "De piloot", "ok": true, "e": "Juist! De piloot zit vooraan in de cockpit en bestuurt het vliegtuig."}, {"t": "De kapitein van een boot", "ok": false, "e": "Nee, een kapitein bestuurt een schip op het water."}, {"t": "De buschauffeur", "ok": false, "e": "Nee, een buschauffeur rijdt met de bus. In een vliegtuig heet de bestuurder een piloot."}, {"t": "Een robot", "ok": false, "e": "Er zit wel een automatische piloot in het vliegtuig die helpt, maar de echte baas is de piloot!"}]}, {"q": "Welke 2 planeten hebben ringen? Kijk goed! 👀", "multi": 2, "a": [{"t": "Mars", "planet": "mars", "ok": false, "e": "Nee! Mars heeft geen ringen, wel twee kleine maantjes."}, {"t": "Saturnus", "planet": "saturn ring", "ok": true, "e": "Juist! Saturnus heeft de grootste en mooiste ringen. Ze bestaan uit miljoenen stukjes ijs en steen."}, {"t": "Aarde", "planet": "earth", "ok": false, "e": "Nee, de aarde heeft geen ringen. Wij hebben één maan."}, {"t": "Uranus", "planet": "uranus ring thin", "ok": true, "e": "Juist! Uranus heeft dunne, donkere ringen. Ze staan bijna rechtop, want Uranus ligt op zijn zij!"}]}, {"q": "Wat is de zon eigenlijk?", "a": [{"t": "Een grote planeet", "ok": false, "e": "Nee! Planeten geven zelf geen licht. De zon wel."}, {"t": "Een ster", "ok": true, "e": "Juist! De zon is een ster, een gigantische bol van heet vuur en gas. Ze lijkt groot omdat ze dicht bij ons staat."}, {"t": "Een maan", "ok": false, "e": "Nee, een maan draait rond een planeet. De zon staat in het midden van ons zonnestelsel."}]}, {"q": "Wat helpt een vliegtuig om in de lucht te blijven?", "a": [{"t": "Zijn vleugels", "ok": true, "e": "Juist! De lucht stroomt snel over de vleugels en duwt het vliegtuig omhoog."}, {"t": "Zijn wielen", "ok": false, "e": "Nee, de wielen zijn voor op de grond, om te landen en op te stijgen."}, {"t": "Zijn raampjes", "ok": false, "e": "Nee! Door de raampjes kan je mooi naar buiten kijken, maar ze houden het vliegtuig niet in de lucht."}, {"t": "De koffers", "ok": false, "e": "Nee hoor, de koffers maken het vliegtuig alleen maar zwaarder!"}]}, {"q": "Welke planeet staat het dichtst bij de zon?", "a": [{"t": "Aarde", "ok": false, "e": "Nee, de aarde staat op de derde plaats: eerst komen Mercurius en Venus."}, {"t": "Mercurius", "ok": true, "e": "Juist! Mercurius is de kleinste planeet en staat het dichtst bij de zon. Hij raast er in 88 dagen omheen."}, {"t": "Jupiter", "ok": false, "e": "Nee, Jupiter staat veel verder, op de vijfde plaats."}, {"t": "Saturnus", "ok": false, "e": "Nee, Saturnus staat heel ver weg, op de zesde plaats."}]}, {"q": "Wat draait er rond de aarde?", "a": [{"t": "De zon", "ok": false, "e": "Andersom! De aarde draait rond de zon."}, {"t": "De maan", "ok": true, "e": "Juist! De maan draait rond de aarde. Dat duurt ongeveer een maand."}, {"t": "Mars", "ok": false, "e": "Nee, Mars is een planeet die net als de aarde rond de zon draait."}]}, {"q": "Wat kan een helikopter dat een vliegtuig niet kan?", "a": [{"t": "Stil in de lucht blijven hangen", "ok": true, "e": "Juist! Een helikopter kan stil blijven hangen en recht omhoog en omlaag vliegen. Handig om mensen te redden!"}, {"t": "Sneller vliegen", "ok": false, "e": "Nee, vliegtuigen zijn juist veel sneller dan helikopters."}, {"t": "Onder water zwemmen", "ok": false, "e": "Haha, nee! Een helikopter kan niet onder water. Dat kan een onderzeeër."}, {"t": "Naar de maan vliegen", "ok": false, "e": "Nee, daar heb je een raket voor nodig. In de ruimte is geen lucht, dus wieken werken daar niet."}]}, {"q": "Wie was de eerste mens die op de maan stapte?", "a": [{"t": "Neil Armstrong", "ok": true, "e": "Juist! In 1969 zette Neil Armstrong als eerste mens een voet op de maan."}, {"t": "Buzz Lightyear", "ok": false, "e": "Haha! Buzz Lightyear is een speelgoedfiguur uit Toy Story. Maar er ging wel een echte Buzz mee: Buzz Aldrin!"}, {"t": "Kapitein Haak", "ok": false, "e": "Nee! Kapitein Haak is een piraat uit Peter Pan. Hij ging nooit naar de maan."}]}, {"q": "Hoe noemen we iemand die naar de ruimte reist?", "a": [{"t": "Een piloot", "ok": false, "e": "Bijna! Een piloot vliegt met een vliegtuig, maar blijft dicht bij de aarde."}, {"t": "Een astronaut", "ok": true, "e": "Juist! Een astronaut reist met een raket naar de ruimte en draagt daar een ruimtepak."}, {"t": "Een duiker", "ok": false, "e": "Nee, een duiker gaat onder water. Al oefenen astronauten wel soms in een groot zwembad!"}, {"t": "Een brandweerman", "ok": false, "e": "Nee, een brandweerman blust branden op aarde."}]}, {"q": "Waar zit de piloot in het vliegtuig?", "a": [{"t": "In de cockpit, helemaal vooraan", "ok": true, "e": "Juist! De cockpit zit vooraan. Daar zijn heel veel knopjes en schermen om het vliegtuig te besturen."}, {"t": "In de staart, achteraan", "ok": false, "e": "Nee, achteraan zit de staart van het vliegtuig. De piloot zit vooraan."}, {"t": "Bij de koffers", "ok": false, "e": "Nee! De koffers zitten in de buik van het vliegtuig. Daar is het koud en donker."}]}, {"q": "Welke planeet is de heetste van allemaal?", "a": [{"t": "Mercurius", "ok": false, "e": "Goed nagedacht, want Mercurius staat het dichtst bij de zon. Toch is Venus nog heter door haar dikke wolkendeken!"}, {"t": "Venus", "ok": true, "e": "Juist! Venus heeft een dikke deken van wolken die de warmte vasthoudt. Het is er meer dan 400 graden!"}, {"t": "Neptunus", "ok": false, "e": "Nee, Neptunus is juist een van de koudste planeten."}, {"t": "Aarde", "ok": false, "e": "Nee, op aarde is het precies goed: niet te warm en niet te koud."}]}, {"q": "Hoe komt een raket de ruimte in?", "a": [{"t": "Met sterke motoren die vuur naar beneden spuwen", "ok": true, "e": "Juist! De motoren duwen heel hard naar beneden en zo schiet de raket omhoog. 3, 2, 1… lancering!"}, {"t": "Met grote vleugels", "ok": false, "e": "Nee, in de ruimte is geen lucht, dus vleugels helpen daar niet."}, {"t": "Met een lange ladder", "ok": false, "e": "Haha, die ladder zou wel héél lang moeten zijn! Nee, een raket gebruikt motoren."}]}, {"q": "Welk vliegend ding heeft geen motor en zweeft gewoon op de wind?", "a": [{"t": "Een helikopter", "ok": false, "e": "Nee, een helikopter heeft een motor die de wieken laat draaien."}, {"t": "Een zweefvliegtuig", "ok": true, "e": "Juist! Een zweefvliegtuig heeft geen motor. Het wordt omhoog getrokken en zweeft dan heel stil op de wind."}, {"t": "Een straaljager", "ok": false, "e": "Nee, een straaljager heeft juist supersterke motoren en is heel snel en luid."}, {"t": "Een raket", "ok": false, "e": "Nee, een raket heeft de sterkste motoren van allemaal!"}]}]'::jsonb
where not exists (select 1 from public.quizzes where title = 'Ruimte Quiz' and school_id is null);

